ing(.horizontal, 30)                    .padding(.top, 10)                                        // Navigation Link to Signup                    NavigationLink(destination: SignupView()) {                        Text("New Here? Sign up")                            .foregroundColor(.white)                            .underline()                            .padding(.top, 20)                    }                }            }        }    }        func loginUser() {        errorMessage = "" // Clear previous errors                Auth.auth().signIn(withEmail: email, password: password) { result, error in            if let error = error {                errorMessage = error.localizedDescription                return            }            print("Successfully logged in as \(result?.user.uid ?? "")!")            // TODO: Later, we will use this success to change the screen to the Home Feed        }    }}                struct LoginView_Previews: PreviewProvider {        static var previews: some View {            LoginView()        }    }